using Backend.Api.Auth;
using Microsoft.Extensions.Options;
namespace Backend.Api.Apis; public static class AuthEndpoints { public static IEndpointRouteBuilder MapAuthEndpoints(this IEndpointRouteBuilder app) { app.MapPost("/auth/login", (LoginRequest request, HttpContext http, SessionService sessions, IOptions<Backend.Api.Auth.SessionOptions> options, ILoggerFactory logs) => { if(!sessions.ValidateCredentials(request.Username,request.Password)) { logs.CreateLogger("Auth").LogWarning("Invalid login attempt for {Username}",request.Username); return Results.Unauthorized(); } var cookie=options.Value; http.Response.Cookies.Append(cookie.CookieName,sessions.Create(request.Username,DateTimeOffset.UtcNow),new CookieOptions{HttpOnly=true,Secure=cookie.SecureCookie,SameSite=SameSiteMode.Strict,MaxAge=TimeSpan.FromMinutes(cookie.ExpirationMinutes),IsEssential=true}); return Results.Ok(new { authenticated=true }); }).AllowAnonymous().WithName("Login"); return app; } public sealed record LoginRequest(string Username,string Password); }